import numpy as np, pickle, time
T=np.load('T.npy');A=np.arange(32)
def circ(L,d): return np.array([[min(7,min((x-z)%L,(z-x)%L)//d) for z in range(L)] for x in range(L)])
def diff(L,d): return np.array([[min(7,abs(x-z)//d) for z in range(L)] for x in range(L)])
F={}
for L,d in ((14,1),(15,1),(16,1),(18,1),(28,2),(30,2),(32,2),(36,2),(48,3),(64,4)): F[f'circ{L}/{d}']=(L,d,circ(L,d))
for L,d in ((8,1),(16,2),(24,3),(32,4),(48,6)): F[f'diff{L}/{d}']=(L,d,diff(L,d))
def run(M,W,Ft,L,rng,rs,it=8,tmax=None):
    ii,jj=np.nonzero(W);O=np.zeros((32,32,8));O[ii,jj,M[ii,jj]]=1;best=None;t0=time.time()
    for _ in range(rs):
        x=rng.integers(0,L,32);z=rng.integers(0,L,32)
        for _ in range(it):
            x=np.stack([O[:,A,Ft[v,z]].sum(1) for v in range(L)],1).argmax(1)
            z=np.stack([O[A[:,None],A,Ft[x,v][:,None]].sum(0) for v in range(L)],1).argmax(1)
        a=(Ft[x[ii],z[jj]]==M[ii,jj]).mean()
        if best is None or a>best[2]: best=(x.copy(),z.copy(),a)
        if tmax and time.time()-t0>tmax: break
    return best
def search(s,budget=16.):
    t=time.time();rng=np.random.default_rng(100+s);M=T[s];W=M>=0;cells=np.argwhere(W);R={};per=budget/len(F)
    for n,(L,d,Ft) in F.items():
        cv=[]
        for f in range(3):
            p=rng.permutation(len(cells));te=cells[p[:143]];W2=W.copy();W2[te[:,0],te[:,1]]=False
            b=run(M,W2,Ft,L,rng,30,tmax=per*.15)
            cv.append((Ft[b[0][te[:,0]],b[1][te[:,1]]]==M[te[:,0],te[:,1]]).mean())
        b=run(M,W,Ft,L,rng,100000,tmax=per*.5)
        R[n]=(float(np.mean(cv)),float(b[2]),b[0],b[1],L,d)
    pickle.dump(R,open(f'R{s}.pkl','wb'))
    print('skill',s,sorted([(round(v[0],3),round(v[1],3),n) for n,v in R.items()],reverse=True)[:6],round(time.time()-t,1))
